def fmt(x,d=2):
    if pd.isna(x):return '—'
    return str(int(x)) if isinstance(x,(int,np.integer)) else f'{x:.{d}f}'
def table(headers,rows):
    return '\n| '+' | '.join(headers)+' |\n| '+' | '.join(['---']*len(headers))+' |\n'+''.join('| '+' | '.join(str(x).replace('|','/') for x in row)+' |\n' for row in rows)+'\n'
def br():return '\n<div class="pagebreak"></div>\n'
